// The hand-made finish — what makes a code-drawn frame look painted by a
// person instead of generated by a computer. Shared by every style.
//
// Vector shapes are too perfect: dead-straight lines, flat fills, motion that
// glides at 30 fps. Hand-made 2D animation has none of that, so every frame
// of the painting goes through this pass:
//
//   boil     every line wobbles a little, and the wobble changes 10× a second
//            (each hand-drawn frame is traced again and never lands in exactly
//            the same place — the "line boil" of classic 2D animation)
//   twos     the painting moves "on twos": a new drawing every 2nd frame (15
//            per second) like cel and cut-out animation; captions stay smooth
//   bleed    ink soaks into the paper: a soft dark halo around dark shapes
//   gold     gilded areas catch the light — a slow sheen sweeps across them,
//            with a few glints (Ottoman gold leaf)
//   paper    real paper under the paint: fibres, cloudy density, mineral
//            pigment grain (multiplied, so ink and colour sit IN the paper)
//   light    a soft lamp falloff on the painting (warm centre, darker edges)
//   breathe  a slow rostrum-camera push-in on every shot, so no shot is a
//            frozen slide
//   grain    film grain + a faint projector flicker over the whole frame
//
// Stories can tune it: meta.finish = { boil: 1.4, twos: true, bleed: 0.3,
// gold: 0.8, grain: 0.07, breathe: 0.025, light: 0.18 } (0/false turns a part
// off), or meta.finish = false for the old clean look.
import { createCanvas } from '@napi-rs/canvas';
import { rng, clamp, lerp } from './core.mjs';

export const STYLE_FINISH = {
  // ink on absorbent card: strong boil, ink bleed, no gold
  inkblot: { boil: 1.5, twos: true, bleed: 0.55, gold: 0, grain: 0.075, flicker: 0.018, breathe: 0.022, light: 0.1, lightTint: [255, 251, 244], paper: { tone: [250, 246, 238], fibres: 0.11, clouds: 14, grit: 10, foxing: 14 } },
  // gouache on burnished paper: gentler boil, gold leaf that shines
  ottoman: { boil: 1.15, twos: true, bleed: 0.3, gold: 0.85, grain: 0.06, flicker: 0.01, breathe: 0.02, light: 0.09, lightTint: [255, 250, 238], paper: { tone: [250, 243, 226], fibres: 0.08, clouds: 12, grit: 13, foxing: 10 } },
};

export function finishOptions(meta) {
  if (meta.finish === false) return null;
  const base = STYLE_FINISH[meta.style] || STYLE_FINISH.inkblot;
  const f = meta.finish || {};
  return { ...base, ...f, paper: f.paper === null || f.paper === false ? null : { ...base.paper, ...(f.paper || {}) } };
}

// ---------- smooth 2-D value noise on a hashed lattice (fast, seeded) ----------
function makeNoise(seed) {
  const R = rng(seed), perm = new Uint16Array(512), val = new Float32Array(256);
  for (let i = 0; i < 256; i++) { perm[i] = i; val[i] = R() * 2 - 1; }
  for (let i = 255; i > 0; i--) { const j = Math.floor(R() * (i + 1)); [perm[i], perm[j]] = [perm[j], perm[i]]; }
  for (let i = 0; i < 256; i++) perm[i + 256] = perm[i];
  return (x, y) => {
    const xi = Math.floor(x), yi = Math.floor(y), fx = x - xi, fy = y - yi;
    const u = fx * fx * (3 - 2 * fx), v = fy * fy * (3 - 2 * fy);
    const a = xi & 255, b = yi & 255;
    const n00 = val[perm[a + perm[b]]], n10 = val[perm[a + 1 + perm[b]]];
    const n01 = val[perm[a + perm[b + 1]]], n11 = val[perm[a + 1 + perm[b + 1]]];
    return lerp(lerp(n00, n10, u), lerp(n01, n11, u), v);
  };
}

// ---------- paper: fibres, cloudy density, pigment grit, foxing ----------
// Returned canvas is meant to be multiplied over a painting.
export function paperGrain(w, h, seed = 3, o = {}) {
  const tone = o.tone || [246, 240, 226], nA = makeNoise(seed), nB = makeNoise(seed + 1), nC = makeNoise(seed + 2), R = rng(seed + 9);
  const cv = createCanvas(w, h), ctx = cv.getContext('2d');
  const img = ctx.createImageData(w, h), d = img.data;
  const clouds = o.clouds ?? 12, grit = o.grit ?? 10;
  for (let y = 0; y < h; y++) for (let x = 0; x < w; x++) {
    // cloudy pulp density (two octaves) + long horizontal "laid" fibres + fine grit
    const c = nA(x / 170, y / 170) * 0.65 + nA(x / 60 + 40, y / 60) * 0.35;
    const laid = nB(x / 300, y / 2.2) * 0.5;
    const g = (R() - 0.5) * grit + nC(x / 2.5, y / 2.5) * grit * 0.6;
    const v = clouds * c + 3 * laid + g;
    const i = (y * w + x) * 4;
    d[i] = clamp(tone[0] + v, 0, 255); d[i + 1] = clamp(tone[1] + v * 1.02, 0, 255); d[i + 2] = clamp(tone[2] + v * 1.12, 0, 255); d[i + 3] = 255;
  }
  ctx.putImageData(img, 0, 0);
  // fibres: short curly hairs, some light (pressed in), most darker
  for (let i = 0; i < (w * h) / 2600; i++) {
    const x = R() * w, y = R() * h, a = R() * Math.PI * 2, l = 5 + R() * 26, dark = R() < 0.75;
    ctx.strokeStyle = dark ? `rgba(110,85,50,${(o.fibres ?? 0.1) * (0.4 + R())})` : `rgba(255,252,240,${0.35 + R() * 0.3})`;
    ctx.lineWidth = 0.6 + R() * 0.8;
    ctx.beginPath(); ctx.moveTo(x, y);
    ctx.bezierCurveTo(x + Math.cos(a + 1.3) * l * 0.4, y + Math.sin(a + 1.3) * l * 0.4, x + Math.cos(a - 0.9) * l * 0.7, y + Math.sin(a - 0.9) * l * 0.7, x + Math.cos(a) * l, y + Math.sin(a) * l);
    ctx.stroke();
  }
  // foxing: age spots with a darker rim (tide line)
  for (let i = 0; i < (o.foxing ?? 10); i++) {
    const x = R() * w, y = R() * h, r = 4 + R() * R() * 34;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, 'rgba(170,120,60,0.06)'); g.addColorStop(0.8, 'rgba(160,105,45,0.12)'); g.addColorStop(1, 'rgba(160,105,45,0)');
    ctx.fillStyle = g; ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill();
  }
  return cv;
}

// Film grain tiles (grey around 128 → used with 'overlay').
function grainTiles(n, size, seed) {
  const R = rng(seed), out = [];
  for (let k = 0; k < n; k++) {
    const cv = createCanvas(size, size), ctx = cv.getContext('2d'), img = ctx.createImageData(size, size), d = img.data;
    for (let i = 0; i < size * size; i++) {
      // roughly gaussian (sum of 3 uniforms), slightly clumped
      const v = 128 + ((R() + R() + R()) / 3 - 0.5) * 230;
      d[i * 4] = d[i * 4 + 1] = d[i * 4 + 2] = v; d[i * 4 + 3] = 255;
    }
    ctx.putImageData(img, 0, 0);
    // soften to a film-like clump (grain is not single-pixel digital noise)
    const soft = createCanvas(size, size), sx = soft.getContext('2d');
    sx.drawImage(cv, 0, 0); sx.globalAlpha = 0.55; sx.filter = 'blur(0.7px)'; sx.drawImage(cv, 0, 0);
    out.push(soft);
  }
  return out;
}

// Displacement fields for the line boil: `phases` drawings that cycle.
function boilFields(w, h, amp, phases, seed) {
  const fields = [];
  for (let p = 0; p < phases; p++) {
    const nx = makeNoise(seed + p * 31), ny = makeNoise(seed + p * 31 + 7), fx = makeNoise(seed + p * 31 + 13), fy = makeNoise(seed + p * 31 + 19);
    // coarse field computed on a 4-px grid, fine jitter per pixel → cheap and smooth
    const gw = Math.ceil(w / 4) + 2, gh = Math.ceil(h / 4) + 2, gx = new Float32Array(gw * gh), gy = new Float32Array(gw * gh);
    for (let j = 0; j < gh; j++) for (let i = 0; i < gw; i++) {
      const x = i * 4, y = j * 4;
      gx[j * gw + i] = amp * (nx(x / 58, y / 58) * 0.75 + fx(x / 17, y / 17) * 0.35);
      gy[j * gw + i] = amp * (ny(x / 58, y / 58) * 0.75 + fy(x / 17, y / 17) * 0.35);
    }
    const dx = new Float32Array(w * h), dy = new Float32Array(w * h);
    for (let y = 0; y < h; y++) {
      const j = y >> 2, ty = (y & 3) / 4;
      for (let x = 0; x < w; x++) {
        const i = x >> 2, tx = (x & 3) / 4, k = j * gw + i;
        const a = lerp(gx[k], gx[k + 1], tx), b = lerp(gx[k + gw], gx[k + gw + 1], tx);
        const c = lerp(gy[k], gy[k + 1], tx), e = lerp(gy[k + gw], gy[k + gw + 1], tx);
        dx[y * w + x] = lerp(a, b, ty); dy[y * w + x] = lerp(c, e, ty);
      }
    }
    fields.push({ dx, dy });
  }
  return fields;
}

// The finish for one renderer. `w, h` = the painting size.
export function createFinish(meta, w, h, frameW, frameH) {
  const o = finishOptions(meta);
  if (!o) return null;
  const seed = (meta.seed || 7) * 13 + 5;
  const fields = o.boil ? boilFields(w, h, o.boil, 4, seed) : null;
  const paper = o.paper ? paperGrain(w, h, seed + 3, o.paper) : null;
  const grains = o.grain ? grainTiles(4, 256, seed + 5) : null;
  const work = createCanvas(w, h), wctx = work.getContext('2d');
  const halo = o.bleed ? createCanvas(w, h) : null;
  const sheen = makeNoise(seed + 77);
  // soft lamp light: warm centre, darker edges (multiplied)
  let light = null;
  if (o.light) {
    light = createCanvas(w, h); const lx = light.getContext('2d');
    const [r, g, b] = o.lightTint || [255, 250, 240];
    const gr = lx.createRadialGradient(w * 0.46, h * 0.4, Math.min(w, h) * 0.15, w * 0.5, h * 0.5, Math.max(w, h) * 0.78);
    gr.addColorStop(0, `rgb(${r},${g},${b})`); gr.addColorStop(0.55, `rgb(${Math.round(r * (1 - o.light * 0.25))},${Math.round(g * (1 - o.light * 0.3))},${Math.round(b * (1 - o.light * 0.35))})`);
    gr.addColorStop(1, `rgb(${Math.round(r * (1 - o.light))},${Math.round(g * (1 - o.light * 1.1))},${Math.round(b * (1 - o.light * 1.25))})`);
    lx.fillStyle = gr; lx.fillRect(0, 0, w, h);
  }

  return {
    options: o,
    // painting time: a new drawing every 2nd frame (15 fps) — like cel animation
    time(t) { return o.twos ? Math.floor(t * 15 + 1e-6) / 15 : t; },
    // slow rostrum push-in on a shot (call before the scene draws)
    breathe(ctx, u, d) {
      if (!o.breathe) return;
      const k = clamp(u / Math.max(1.5, d)), z = 1 + o.breathe * (k * (2 - k)); // ease-out
      ctx.translate(w / 2, h * 0.46); ctx.scale(z, z); ctx.translate(-w / 2, -h * 0.46);
    },
    // painting canvas → finished painting (in place); t = real time
    painting(src, t) {
      const step = Math.floor(t * 10 + 1e-6); // boil + glints change 10× a second
      if (fields || o.gold) {
        const sctx = src.getContext('2d');
        const inp = sctx.getImageData(0, 0, w, h), s = inp.data;
        const out = wctx.createImageData(w, h), q = out.data;
        const F = fields ? fields[step % fields.length] : null;
        const ts = o.twos ? Math.floor(t * 15 + 1e-6) / 15 : t; // the sheen moves with the drawings
        const gold = o.gold || 0, band = ts * 0.55; // sheen sweep position
        for (let y = 0; y < h; y++) {
          for (let x = 0; x < w; x++) {
            const p = y * w + x;
            let r, g, b, a;
            if (F) {
              let sx = x + F.dx[p], sy = y + F.dy[p];
              if (sx < 0) sx = 0; else if (sx > w - 1.001) sx = w - 1.001;
              if (sy < 0) sy = 0; else if (sy > h - 1.001) sy = h - 1.001;
              const ix = sx | 0, iy = sy | 0, fx = sx - ix, fy = sy - iy;
              const i00 = (iy * w + ix) * 4, i10 = i00 + 4, i01 = i00 + w * 4, i11 = i01 + 4;
              const w00 = (1 - fx) * (1 - fy), w10 = fx * (1 - fy), w01 = (1 - fx) * fy, w11 = fx * fy;
              r = s[i00] * w00 + s[i10] * w10 + s[i01] * w01 + s[i11] * w11;
              g = s[i00 + 1] * w00 + s[i10 + 1] * w10 + s[i01 + 1] * w01 + s[i11 + 1] * w11;
              b = s[i00 + 2] * w00 + s[i10 + 2] * w10 + s[i01 + 2] * w01 + s[i11 + 2] * w11;
              a = s[i00 + 3] * w00 + s[i10 + 3] * w10 + s[i01 + 3] * w01 + s[i11 + 3] * w11;
            } else { r = s[p * 4]; g = s[p * 4 + 1]; b = s[p * 4 + 2]; a = s[p * 4 + 3]; }
            if (gold && r > 120 && g > 85) {
              // gold leaf: yellow with g/r 0.74–0.93 and little blue
              const gr = g / r, br = b / r;
              if (gr > 0.74 && gr < 0.93 && br < 0.56 && r - b > 70) {
                // a broad diagonal sheen that drifts, plus slow shimmering patches
                const d = ((x * 0.62 + y * 0.38) / w - band) % 1.6;
                const sw = Math.exp(-Math.pow((d < 0 ? d + 1.6 : d) - 0.8, 2) / 0.018);
                const n = sheen(x / 90 + ts * 0.15, y / 90) * 0.5 + 0.5;
                const k = gold * (0.55 * sw + 0.22 * n * n);
                r = r + (255 - r) * k; g = g + (246 - g) * k * 0.92; b = b + (200 - b) * k * 0.55;
              }
            }
            const i = p * 4; q[i] = r; q[i + 1] = g; q[i + 2] = b; q[i + 3] = a;
          }
        }
        // glints: a few tiny stars on the brightest gold, re-chosen every step
        sctx.putImageData(out, 0, 0);
        if (gold) {
          const R = rng(step * 977 + seed);
          for (let k = 0; k < 40; k++) {
            const x = (R() * (w - 4)) | 0, y = (R() * (h - 4)) | 0, i = (y * w + x) * 4;
            const r = q[i], g = q[i + 1], b = q[i + 2];
            if (r > 200 && g > 170 && b < 150 && g / r > 0.74) {
              const L = 5 + R() * 9; sctx.save(); sctx.globalAlpha = 0.5 * gold; sctx.strokeStyle = '#fffbe8'; sctx.lineWidth = 1.4;
              sctx.beginPath(); sctx.moveTo(x - L, y); sctx.lineTo(x + L, y); sctx.moveTo(x, y - L); sctx.lineTo(x, y + L); sctx.stroke(); sctx.restore();
            }
          }
        }
      }
      const ctx = src.getContext('2d');
      // ink bleed: a blurred copy, kept only where it is darker → a soft halo where
      // ink meets paper (flat areas stay exactly as painted)
      if (halo) {
        const hx = halo.getContext('2d'); hx.clearRect(0, 0, w, h); hx.filter = 'blur(2.6px)'; hx.drawImage(src, 0, 0); hx.filter = 'none';
        ctx.save(); ctx.globalCompositeOperation = 'darken'; ctx.globalAlpha = o.bleed; ctx.drawImage(halo, 0, 0); ctx.restore();
      }
      if (paper) { ctx.save(); ctx.globalCompositeOperation = 'multiply'; ctx.drawImage(paper, 0, 0); ctx.restore(); }
      if (light) { ctx.save(); ctx.globalCompositeOperation = 'multiply'; ctx.drawImage(light, 0, 0); ctx.restore(); }
      return src;
    },
    // whole frame: film grain + flicker (changes 12× a second)
    frame(ctx, t) {
      const step = Math.floor(t * 12 + 1e-6);
      if (grains) {
        const R = rng(step * 131 + 3), tile = grains[step % grains.length];
        const pat = ctx.createPattern(tile, 'repeat');
        ctx.save(); ctx.globalCompositeOperation = 'overlay'; ctx.globalAlpha = o.grain;
        ctx.translate(-((R() * 256) | 0), -((R() * 256) | 0)); ctx.fillStyle = pat; ctx.fillRect(0, 0, frameW + 256, frameH + 256);
        ctx.restore();
      }
      if (o.flicker) {
        const R = rng(step * 17 + 11), f = R() * o.flicker;
        ctx.fillStyle = `rgba(30,20,10,${f})`; ctx.fillRect(0, 0, frameW, frameH);
      }
    },
  };
}
